import {addUsage, shouldContinueToolLoop} from './orchestratorHelpers.js';
import type {ToolRegistry} from './tools/registry.js';
import type {ToolCall, UsageMetadata} from '../types/ai.js';

// All three conditions matter; dropping the registry check spins the tool loop.

const A_TOOL: ToolCall[] = [{id: 't1', name: 'lookup', input: {}}];
const REGISTRY = {} as ToolRegistry;
const FIRST: UsageMetadata = {inputTokens: 11, outputTokens: 2, totalTokens: 13};
const SECOND: UsageMetadata = {inputTokens: 23, outputTokens: 3, totalTokens: 26};

describe('addUsage', () => {
  it('sums every token field of two reported rounds', () => {
    expect(addUsage(FIRST, SECOND)).toEqual({inputTokens: 34, outputTokens: 5, totalTokens: 39});
  });

  it('takes the reported round alone when the other reported nothing', () => {
    expect(addUsage(FIRST, undefined)).toEqual(FIRST);
    expect(addUsage(undefined, SECOND)).toEqual(SECOND);
  });

  it('stays undefined when no round reported usage', () => {
    expect(addUsage(undefined, undefined)).toBeUndefined();
  });
});

